package com.joysistvi.CyberAccess.service;
import com.joysistvi.CyberAccess.model.DrinkOrderItems; import com.joysistvi.CyberAccess.repo.*; import java.util.List;
public class DrinkOrderItemsServiceImpl implements DrinkOrderItemsService {private final DrinkOrderItemsRepo repo; public DrinkOrderItemsServiceImpl(){this(new DrinkOrderItemsRepoImpl());} public DrinkOrderItemsServiceImpl(DrinkOrderItemsRepo r){repo=r;} public List<DrinkOrderItems> getAll(){return repo.getAll();} public List<DrinkOrderItems> getByOrderId(int id){return id>0?repo.getByOrderId(id):List.of();} public boolean add(DrinkOrderItems x){if(x==null||x.getOrderId()<=0||x.getDrinkItemId()<=0||x.getQuantity()<=0||x.getUnitPrice()<0)return false;return repo.add(x);} public boolean delete(int id){return id>0&&repo.delete(id);}}
